// Act As writes: only a real admin (users.is_admin re-checked on every call)
// may change the acted-as user's Discord settings. Linking stays blocked.
function beta_discord_act_as_ok(): bool {
    if (empty($_SESSION['admin_act_as_active'])) return true;
    if (($_SESSION['admin_act_as_actor_role'] ?? '') !== 'admin') return false;
    $aid = (int) ($_SESSION['admin_act_as_actor_user_id'] ?? 0);
    if ($aid <= 0) return false;
    include '/var/www/config/database.php';
    $c = @new mysqli($db_servername, $db_username, $db_password, 'website');
    if ($c->connect_error) return false;
    $st = $c->prepare('SELECT is_admin FROM users WHERE id = ? LIMIT 1');
    if (!$st) { $c->close(); return false; }
    $st->bind_param('i', $aid); $st->execute();
    $row = $st->get_result()->fetch_assoc(); $st->close(); $c->close();
    return (int) ($row['is_admin'] ?? 0) === 1;
}
// The user's saved server (discord_users.guild_id) is the only server beta acts on.
function beta_discord_guild(): string {
    if (!beta_discord_act_as_ok()) beta_cm_fail('Discord changes are disabled while acting as another user.', 403);
    $uid = (int) ($_SESSION['user_id'] ?? 0);
    if ($uid <= 0) beta_cm_fail('session_expired', 401);
    include '/var/www/config/database.php';
    $c = @new mysqli($db_servername, $db_username, $db_password, 'website');
    if ($c->connect_error) beta_cm_fail('Discord settings are unavailable right now.', 503);
    $st = $c->prepare('SELECT guild_id FROM discord_users WHERE user_id = ?');
    $st->bind_param('i', $uid); $st->execute();
    $row = $st->get_result()->fetch_assoc(); $st->close(); $c->close();
    $g = trim((string) ($row['guild_id'] ?? ''));
    if (!preg_match('/^\d{15,22}$/', $g)) beta_cm_fail('Pick your Discord server first.');
    // Every change and send re-checks that the user still owns the server.
    if ($_SERVER['REQUEST_METHOD'] !== 'GET') beta_discord_owner($uid, $g);
    return $g;
}
// Shared with the live dashboard (dashboard/includes/discord_guard.php).
function beta_discord_owner(int $uid, string $guild): void {
    require_once '/var/www/dashboard/includes/discord_guard.php';
    discord_guard_owner($uid, $guild);
}
// Channel and role IDs on the bot's view of that server.
function beta_discord_ids(string $guild, string $kind): array {
    static $cache = [];
    if (isset($cache[$kind])) return $cache[$kind];
    include '/var/www/config/discord.php';
    $ctx = stream_context_create(['http' => ['header' => "Authorization: Bot $bot_token\r\n", 'method' => 'GET', 'timeout' => 10, 'ignore_errors' => true]]);
    $r = @file_get_contents("https://discord.com/api/v10/guilds/$guild/$kind", false, $ctx);
    $d = json_decode((string) $r, true);
    if (!is_array($d) || !array_is_list($d)) beta_cm_fail('Could not check your Discord server right now. Please try again.', 502);
    return $cache[$kind] = array_map(fn($x) => (string) ($x['id'] ?? ''), $d);
}
function beta_discord_check(string $guild, array $in, array $channels, array $roles): void {
    foreach (array_merge($channels, $roles) as $k) {
        if (!isset($in[$k]) || $in[$k] === '' || $in[$k] === null) continue;
        if (!is_string($in[$k]) && !is_int($in[$k])) beta_cm_fail('That ID is not valid.');
        if (!preg_match('/^\d{15,22}$/', (string) $in[$k])) beta_cm_fail('That ID is not valid.');
        if (!in_array((string) $in[$k], beta_discord_ids($guild, in_array($k, $channels, true) ? 'channels' : 'roles'), true)) beta_cm_fail(in_array($k, $channels, true) ? 'That channel is not in your Discord server.' : 'That role is not in your Discord server.');
    }
}
